    /**
     * Draw the GUI texts
     *
     * @param screenElements Elements that contain the text
     * @param inventorySlot  Controller slot
     */
    @Override
    protected void drawTexts(DynamicPositionedColumn screenElements, SlotWidget inventorySlot) {
        screenElements.setSynced(false)
            .setSpace(0);

        screenElements
            .widget(
                new TextWidget(StatCollector.translateToLocal("GT5U.gui.multimachine.incomplete_structure"))
                    .setDefaultColor(COLOR_TEXT_WHITE.get())
                    .setEnabled(widget -> !mMachine))
            .widget(new FakeSyncWidget.BooleanSyncer(() -> mMachine, val -> mMachine = val));

        screenElements.widget(
            new TextWidget(StatCollector.translateToLocal("gt.blockmachines.multimachine.ig.elevator.gui.ready"))
                .setDefaultColor(COLOR_TEXT_WHITE.get())
                .setEnabled(widget -> mMachine));

        screenElements.widget(
            new TextWidget(StatCollector.translateToLocal("gt.blockmachines.multimachine.ig.elevator.gui.noRecipe"))
                .setDefaultColor(COLOR_TEXT_WHITE.get())
                .setEnabled(widget -> mMachine && !getBaseMetaTileEntity().isActive()));

        screenElements.widget(
            new TextWidget(StatCollector.translateToLocal("gt.blockmachines.multimachine.ig.elevator.gui.recipe"))
                .setDefaultColor(COLOR_TEXT_WHITE.get())
                .setEnabled(widget -> mMachine && getBaseMetaTileEntity().isActive()));

        screenElements.widget(
            TextWidget
                .dynamicString(
                    () -> StatCollector.translateToLocal("gt.blockmachines.multimachine.ig.elevator.gui.numOfModules")
                        + ": "
                        + getNumberOfModules()
                        + " / "
                        + getModuleCapacity(motorTier))
                .setDefaultColor(COLOR_TEXT_WHITE.get())
                .setEnabled(widget -> getErrorDisplayID() == 0));

        screenElements.widget(
            TextWidget
                .dynamicString(
                    () -> StatCollector.translateToLocal("machine.mtspaceelevator.gui.motor") + ": "
                        + motorTierName(motorTier))
                .setDefaultColor(COLOR_TEXT_WHITE.get())
                .setEnabled(widget -> mMachine && getErrorDisplayID() == 0));
    }

    /**
     * Add UI widgets to this GUI. The TT base panel (background, status, power buttons, parameter LEDs) is kept, and
     * only the travel button is added on top: this elevator has a single structure piece, so GT5U's "extended
     * structure" toggle and the GTNH Intergalactic contributor button do not belong here.
     *
     * @param builder      Used UI builder
     * @param buildContext Build context
     */
    @Override
    public void addUIWidgets(ModularWindow.Builder builder, UIBuildContext buildContext) {
        super.addUIWidgets(builder, buildContext);

        if (Mods.GalacticraftCore.isModLoaded()) {
            addTeleportationButton(builder);
        }
    }

    @Optional.Method(modid = Mods.ModIDs.GALACTICRAFT_CORE)
    private void addTeleportationButton(ModularWindow.Builder builder) {
        // Teleportation button
        builder.widget(new ButtonWidget().setOnClick((clickData, widget) -> {
            if (!widget.getContext()
                .isClient()) {
                if (getBaseMetaTileEntity().isAllowedToWork() && motorTier > 0) {
                    EntityPlayer player = widget.getContext()
                        .getPlayer();
                    if (player instanceof EntityPlayerMP playerBase) {
                        final GCPlayerStats stats = GCPlayerStats.get(playerBase);
                        stats.coordsTeleportedFromX = playerBase.posX;
                        stats.coordsTeleportedFromZ = playerBase.posZ;
                        try {
                            WorldUtil.toCelestialSelection(
                                playerBase,
                                stats,
                                ElevatorUtil.getPlanetaryTravelTier(motorTier),
                                GuiCelestialSelection.MapMode.TELEPORTATION);
                        } catch (final Exception e) {
                            GTNHIntergalactic.LOG.error(e);
                        }
                    }
                }
            }
        })
            .setPlayClickSound(false)
            .setBackground(() -> {
                List<UITexture> ret = new ArrayList<>();
                ret.add(TecTechUITextures.BUTTON_STANDARD_16x16);
                ret.add(IG_UITextures.OVERLAY_BUTTON_PLANET_TELEPORT);
                return ret.toArray(new IDrawable[0]);
            })
            .setPos(174, doesBindPlayerInventory() ? 132 : 156)
            .setSize(16, 16)
            .addTooltip(StatCollector.translateToLocal("ig.button.travel"))
            .setTooltipShowUpDelay(TOOLTIP_DELAY));
    }

